def all_subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def contains(value,name):
    for item in all_subterms(value):
        if item[0]==name:
            return True
    return False

def collect_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    by_id={}
    for node in nodes:
        if isinstance(node,dict):
            by_id[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in by_id:
                continue
            seen.add(node_id)
            node=by_id[node_id]
            for term in all_subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='representatives_of' and len(item)>1:
            key=str(item[1])
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
        elif name=='employees_of' and len(item)>1:
            if contains(item[1],'affiliates_of'):
                tags.add('controlled_employees')
            else:
                tags.add('recipient_employees')
        elif name=='internal_personnel_of':
            tags.add('recipient_employees')
        elif name=='independent_contractors_of':
            tags.add('contractors')
        elif name=='consultants_of':
            tags.add('consultants')
        elif name=='agents_of':
            tags.add('agents')
        elif name in ('professional_advisors_of','legal_advisors_of','financial_advisors_of','accountants_of','lenders_of'):
            tags.add('professional_advisers')
        elif name=='third_parties':
            tags.add('third_parties')
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=collect_entries(premises)
    definitions=[]
    definition_roots=[]
    old_permissions=[]
    old_prohibitions=[]
    old_disposals=[]
    retention_permissions=[]
    retention_prohibitions=[]
    disclosure_bindings=[]
    disposal_bindings=[]
    disclosure_absence=[]
    disposal_absence=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
        elif term[0]=='source_disclosure_binding' and len(term)>=12:
            disclosure_bindings.append((term,root))
        elif term[0]=='source_disposal_binding' and len(term)>=10:
            disposal_bindings.append((term,root))
        elif term[0]=='disposal_obligation' and len(term)==5:
            old_disposals.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0] in ('retention_prohibition','absolute_retention_prohibition'):
            retention_prohibitions.append(root)
        elif term[0] in ('complete_source_no_disclosure_permission',):
            disclosure_absence.append(root)
        elif term[0] in ('complete_source_no_disposal_obligation',):
            disposal_absence.append(root)
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not contains(action[1],'confidential_information'):
            continue
        item=(root,role_tags(action[2],definitions),action[2])
        if term[0]=='permission':
            old_permissions.append(item)
        else:
            old_prohibitions.append(item)
    if task in ('nda-5','nda-7'):
        positive=[]
        relevant=[]
        prohibitive=[]
        for term,root in disclosure_bindings:
            relevant.append(root)
            effect=term[1]
            operative=effect in ('operative_permission','prohibition_with_class_permission')
            if operative and task=='nda-5' and term[2]=='stated':
                positive.append(root)
            if operative and task=='nda-7' and 'stated' in (term[4],term[5],term[6],term[7]):
                positive.append(root)
            if effect=='operative_prohibition_only' and task=='nda-7':
                prohibitive.append(root)
        for root,tags,recipient in old_permissions:
            relevant.append(root)
            if task=='nda-5' and 'recipient_employees' in tags:
                positive.append(root)
            if task=='nda-7' and tags.intersection({'contractors','consultants','agents','professional_advisers','third_parties'}):
                positive.append(root)
        if positive:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(positive)}
        for root,tags,recipient in old_prohibitions:
            relevant.append(root)
            if task=='nda-7' and not contains(recipient,'outsiders_to') and 'third_parties' in tags:
                prohibitive.append(root)
            if task=='nda-5' and 'recipient_employees' in tags:
                prohibitive.append(root)
        if prohibitive:
            return {'handled':True,'answer':'Contradiction','used_nodes':unique(prohibitive)}
        if relevant or disclosure_absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+definition_roots+disclosure_absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='nda-16':
        endpoints=[]
        relevant=[]
        endpoint_choices={'agreement_end','relationship_or_project_end','service_end','relationship_nonformation_deadline','multiple_explicit_triggers'}
        for term,root in disposal_bindings:
            relevant.append(root)
            if term[1]!='not_a_disposal_action' and (term[2] in endpoint_choices or term[3] in endpoint_choices):
                endpoints.append(root)
        for term,root in old_disposals:
            if contains(term[2],'return_to') or contains(term[2],'destroy'):
                relevant.append(root)
                if contains(term[3],'agreement_termination') or contains(term[3],'relationship_termination') or contains(term[3],'service_termination') or contains(term[3],'relationship_nonformation_deadline') or contains(term[3],'purpose_completion'):
                    endpoints.append(root)
        if endpoints:
            return {'handled':True,'answer':'Entailment','used_nodes':unique(endpoints)}
        if relevant or disposal_absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+disposal_absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(retention_permissions)}
    explicit_permissions=[]
    explicit_prohibitions=[]
    full_disposals=[]
    relevant=[]
    full_scopes={'confidential_information_only','confidential_information_and_copies','information_copies_and_derivatives','all_source_stated_materials'}
    for term,root in disposal_bindings:
        relevant.append(root)
        effect=term[6]
        if effect in ('explicit_retention_permission','both_permission_and_prohibition'):
            explicit_permissions.append(root)
        if effect in ('explicit_retention_prohibition','both_permission_and_prohibition'):
            explicit_prohibitions.append(root)
        if effect=='no_explicit_retention_effect_in_window' and term[1]!='not_a_disposal_action' and (term[4] in full_scopes or term[5] in full_scopes):
            full_disposals.append(root)
    if explicit_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':unique(explicit_permissions)}
    if retention_prohibitions or explicit_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(retention_prohibitions+explicit_prohibitions)}
    if full_disposals:
        return {'handled':True,'answer':'Contradiction','used_nodes':unique(full_disposals)}
    old_relevant=[]
    for term,root in old_disposals:
        if contains(term[2],'return_to') or contains(term[2],'destroy'):
            old_relevant.append(root)
    if relevant or old_relevant or disposal_absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant+old_relevant+disposal_absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

